import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as a,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Google AI subscriptions and quota","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/gemini/google-pro.md","filePath":"products/ai-coding/gemini/google-pro.md","lastUpdated":1787107158000}'),i={name:"products/ai-coding/gemini/google-pro.md"};function n(s,t,l,d,h,c){return a(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="google-ai-subscriptions-and-quota" tabindex="-1">Google AI subscriptions and quota <a class="header-anchor" href="#google-ai-subscriptions-and-quota" aria-label="Permalink to &quot;Google AI subscriptions and quota&quot;">​</a></h1><blockquote><p>Your subscription tier decides which models you can use, how much, and whether you get Google Cloud credit. This page covers <strong>payment, quota, and how Pro entitlements map onto the family</strong>. For how each product works, see its own page. The full four-tier table lives only in the <a href="./gemini-cheatsheet.html#subscription-tiers">cheatsheet</a>.</p></blockquote><h2 id="one-thing-to-get-straight-first" tabindex="-1">One thing to get straight first <a class="header-anchor" href="#one-thing-to-get-straight-first" aria-label="Permalink to &quot;One thing to get straight first&quot;">​</a></h2><p>The family is <strong>not unlocked by a single subscription</strong>. There are two separate paid entry points:</p><table tabindex="0"><thead><tr><th>Entry point</th><th>Covers</th><th>Aimed at</th></tr></thead><tbody><tr><td>Google AI subscription (Plus / Pro / Ultra)</td><td>usage for the Gemini app, Jules, Antigravity, Flow and so on</td><td>individual developers</td></tr><tr><td><a href="./code-assist.html">Gemini Code Assist</a> Standard / Enterprise</td><td>IDE extension capability and compliance features</td><td>teams and organisations</td></tr></tbody></table><p><strong>Buying personal AI Pro does not turn Code Assist into the enterprise product</strong> — they are separate. Team compliance requirements are met by the Code Assist edition, not by a personal subscription.</p><p><strong>Since 2026-06-18</strong>, individual / Pro / Ultra accounts can no longer reach Gemini CLI or the Code Assist IDE extensions via Login with Google. The individual terminal and IDE entry point is <a href="./antigravity.html">Antigravity</a>. Standard / Enterprise and paid API keys are unchanged. <a href="https://developers.google.com/gemini-code-assist/docs/deprecations/code-assist-individuals" target="_blank" rel="noreferrer">Official deprecation</a>.</p><h2 id="the-four-tiers" tabindex="-1">The four tiers <a class="header-anchor" href="#the-four-tiers" aria-label="Permalink to &quot;The four tiers&quot;">​</a></h2><p>Subscriptions come in four tiers: <strong>AI Plus / AI Pro / AI Ultra 5x / AI Ultra 20x</strong>. Storage, model multipliers, Cloud credit and monthly Flow credits are compared in the <a href="./gemini-cheatsheet.html#subscription-tiers">cheatsheet</a> and are not duplicated here.</p><p>A few facts that actually change which tier you should pick:</p><p><strong>1. Extended context starts at Pro.</strong> The official comparison marks Pro and above as 1,000,000 tokens. This is the only context figure in the family that can be cited.</p><p><strong>2. Google Cloud credit exists only at Pro and above.</strong> It is delivered through the Google Developer Program: Pro US$10/month, Ultra 5x US$40/month, Ultra 20x US$100/month. If you intend to use the Gemini API or Vertex AI, this is the main reason to choose Pro over Plus.</p><p><strong>3. Quota for the agent products is described only qualitatively.</strong> The official comparison for Jules and Antigravity says only that &quot;task count and concurrent task count increase with the tier&quot; and <strong>gives no specific numbers</strong>.</p><p><strong>4. Flow credits are numeric.</strong> 50/day on the free trial, 200/month on Plus, 1,000/month on Pro, 10,000 or 25,000/month on Ultra. Details live only on <a href="./flow.html#credits">Flow</a>.</p><h2 id="coding-relevant-pro-entitlements" tabindex="-1">Coding-relevant Pro entitlements <a class="header-anchor" href="#coding-relevant-pro-entitlements" aria-label="Permalink to &quot;Coding-relevant Pro entitlements&quot;">​</a></h2><p>Source: <a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Use Google AI Pro benefits</a>. Only the items a frontend engineer will actually hit; the rest of the subscription list is not copied here.</p><table tabindex="0"><thead><tr><th>Entitlement</th><th>For a frontend engineer</th><th>Where to read it</th></tr></thead><tbody><tr><td><strong>Google Flow</strong></td><td>landing-page / launch / product-demo video</td><td><a href="./flow.html">Flow</a> (credits live on that page)</td></tr><tr><td><strong>Google Antigravity</strong> higher limits and prioritized traffic</td><td>the individual daily entry point after 2026-06-18</td><td><a href="./antigravity.html">Antigravity</a></td></tr><tr><td><strong>Jules</strong> higher task / concurrency / model access</td><td>asynchronous cloud PRs</td><td><a href="./jules.html">Jules</a></td></tr><tr><td><strong>Google AI Studio</strong></td><td>tune the model, call the API; Pro raises the Gemini 3.1 Pro and Nano Banana Pro caps</td><td><a href="./ai-studio.html">AI Studio</a></td></tr><tr><td><strong>Gemini in Android Studio</strong></td><td>higher completion and reasoning quota on Android projects; code is not used for training</td><td>no standalone page; IDE entry is <a href="./code-assist.html">Code Assist</a></td></tr><tr><td><strong>Google Developer Program premium</strong></td><td>US$10 Cloud credit, higher Code Assist quota, 30 Firebase Studio workspaces. <strong>Cannot</strong> be shared with family-group members</td><td><a href="https://developers.google.com/profile/help/benefits#premium-benefits" target="_blank" rel="noreferrer">Developer Program</a></td></tr><tr><td><strong>Gemini app + Deep Research</strong></td><td>in-depth research outside the editor</td><td><a href="https://gemini.google/overview/deep-research/" target="_blank" rel="noreferrer">Deep Research</a></td></tr><tr><td><strong>Gemini Spark</strong> (US only)</td><td>a personal agent inside Gemini apps that runs workflows against a goal</td><td>no standalone page; <a href="https://support.google.com/gemini/answer/17094507" target="_blank" rel="noreferrer">official note</a></td></tr><tr><td><strong>Gemini Notebook</strong></td><td>research / writing assistant; Pro raises Audio Overviews and similar caps, up to <strong>300</strong> sources per notebook</td><td>no standalone page; <a href="https://support.google.com/gemininotebook/answer/16213268" target="_blank" rel="noreferrer">official note</a></td></tr><tr><td><strong>Gemini in Chrome auto browse</strong> (US only)</td><td>Gemini in Chrome runs multi-step web tasks (compare prices, book a hotel). Chrome 144+</td><td>no standalone page; <a href="https://support.google.com/gemini/answer/16821166" target="_blank" rel="noreferrer">official note</a></td></tr><tr><td><strong>Google Flow Music</strong></td><td>songs / music videos; Pro maps to Flow Music&#39;s Plus plan: <strong>10,000 music credits / month</strong> (~2,000 songs), 12 concurrent generations. <strong>Separate from Flow video credits</strong></td><td><a href="https://www.flowmusic.app/" target="_blank" rel="noreferrer">flowmusic.app</a></td></tr></tbody></table><p>When the allocation runs out, Pro / Ultra can buy extra AI credits for Gemini, <a href="./flow.html">Flow</a> and <a href="./antigravity.html">Antigravity</a>. How to manage them: <a href="https://support.google.com/googleone/answer/16287445" target="_blank" rel="noreferrer">Manage AI credits</a>.</p><h2 id="what-else-the-plan-includes" tabindex="-1">What else the plan includes <a class="header-anchor" href="#what-else-the-plan-includes" aria-label="Permalink to &quot;What else the plan includes&quot;">​</a></h2><p>The same Pro plan also includes Dreambeans (US only), Health Premium, Home Premium, TV Create Hub (US only), Gemini in Earth, and Photos Remix / Photo to video. <strong>None of that is about coding.</strong> This site does not document them.</p><h2 id="which-tier-to-pay-for" tabindex="-1">Which tier to pay for <a class="header-anchor" href="#which-tier-to-pay-for" aria-label="Permalink to &quot;Which tier to pay for&quot;">​</a></h2><p>Decide by <strong>which tool you mainly use</strong>, not by which tier has the longest feature list:</p><table tabindex="0"><thead><tr><th>Your main usage</th><th>Suggestion</th><th>Reasoning</th></tr></thead><tbody><tr><td>Occasional questions in the terminal</td><td>start on the free quota</td><td>upgrade when you run out, do not pre-buy</td></tr><tr><td>Daily terminal work on a personal account</td><td>Pro + <a href="./antigravity.html">Antigravity</a></td><td>after 2026-06-18, individual / Pro / Ultra no longer use Gemini CLI via Login with Google</td></tr><tr><td>Gemini CLI daily (Standard / Enterprise or API key)</td><td>Pro</td><td>extended context and Cloud credit both start here</td></tr><tr><td>Integrating through the Gemini API</td><td>Pro or above</td><td>mostly for the US$10 Cloud credit</td></tr><tr><td>Heavy Jules / Antigravity task volume</td><td>Ultra</td><td>concurrency and task count rise with the tier</td></tr><tr><td>Regular landing-page / product-demo video</td><td>Pro or above + <a href="./flow.html">Flow</a></td><td>monthly credits jump from 200 to 1,000; the free 50/day is only a trial</td></tr><tr><td>A hard team compliance requirement</td><td>use a <a href="./code-assist.html">Code Assist</a> edition</td><td>personal subscriptions do not offer VPC-SC or IP indemnification</td></tr></tbody></table><p><strong>The order matters: exhaust the free quota until it genuinely is not enough, then upgrade.</strong> Doing it the other way round means paying for capacity you never use, and never learning your real order of consumption.</p><h2 id="credit-is-not-a-hard-cap" tabindex="-1">Credit is not a hard cap <a class="header-anchor" href="#credit-is-not-a-hard-cap" aria-label="Permalink to &quot;Credit is not a hard cap&quot;">​</a></h2><p>This is the easiest trap: <strong>Google Cloud credit is money you were given. Nothing stops automatically when it runs out, and the overage bills normally.</strong></p><p>Set a budget before running any batch script:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GCP console → Billing → Budgets &amp; alerts → create a budget</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>set the amount to your credit amount (US$10 on Pro)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>alert thresholds: 50% / 90% / 100%</span></span></code></pre></div><p><strong>Note that a budget only sends notifications; it does not disable the service.</strong> For a genuine hard stop, the official documentation&#39;s approach is to publish budget notifications to Pub/Sub and have a function unlink the billing account, which you have to build yourself:</p><ul><li><a href="https://cloud.google.com/billing/docs/how-to/notify" target="_blank" rel="noreferrer">Set up budget notifications</a></li><li><a href="https://cloud.google.com/billing/docs/how-to/disable-billing-with-notifications" target="_blank" rel="noreferrer">Disable billing automatically with notifications</a></li></ul><p>The two operations most likely to overspend: <strong>a single long-context call</strong> (far more expensive than an interactive exchange) and <strong>unattended batch scripts</strong>. Configure the budget before either.</p><h2 id="security-practices" tabindex="-1">Security practices <a class="header-anchor" href="#security-practices" aria-label="Permalink to &quot;Security practices&quot;">​</a></h2><p>Beyond quota, these are worth setting up:</p><table tabindex="0"><thead><tr><th>Practice</th><th>How</th></tr></thead><tbody><tr><td>Let the agent auto-execute only in trusted directories</td><td>Gemini CLI <code>security.folderTrust.enabled</code>, see the <a href="./gemini-cheatsheet.html#common-settings-keys">cheatsheet</a></td></tr><tr><td>Isolate agent changes on their own branch</td><td>branch before starting, review by diff afterwards</td></tr><tr><td>Human confirmation for important changes</td><td>Jules plan approval, Antigravity plan artifacts</td></tr><tr><td>Read the changes regularly instead of only the conclusion</td><td>an agent&#39;s verification record is a hint, not a substitute for review</td></tr></tbody></table><blockquote><p>⚠️ Older docs contained configuration keys such as <code>security.allowedCommands</code> / <code>security.deniedCommands</code> / <code>security.sandboxMode</code>. <strong>They do not exist in the official documentation.</strong> The security-related settings that really exist are a small set including folder trust, listed in the <a href="./gemini-cheatsheet.html#common-settings-keys">cheatsheet</a>.</p></blockquote><h2 id="where-the-products-are" tabindex="-1">Where the products are <a class="header-anchor" href="#where-the-products-are" aria-label="Permalink to &quot;Where the products are&quot;">​</a></h2><p>This page does not repeat the product introductions; go straight to the page you want:</p><ul><li>terminal → <a href="./gemini-cli.html">Gemini CLI</a></li><li>autonomous development platform → <a href="./antigravity.html">Antigravity</a></li><li>asynchronous cloud tasks → <a href="./jules.html">Jules</a></li><li>interactive prototypes → <a href="./canvas.html">Canvas</a></li><li>landing-page / launch / product-demo video → <a href="./flow.html">Google Flow</a></li><li>IDE extension → <a href="./code-assist.html">Code Assist</a></li><li>models and API → <a href="./ai-studio.html">AI Studio</a></li></ul><h2 id="official-resources" tabindex="-1">Official resources <a class="header-anchor" href="#official-resources" aria-label="Permalink to &quot;Official resources&quot;">​</a></h2><ul><li><a href="https://one.google.com/about/google-ai-plans/" target="_blank" rel="noreferrer">Google AI plan comparison</a></li><li><a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Google AI Pro benefits</a></li><li><a href="https://developers.google.com/program" target="_blank" rel="noreferrer">Google Developer Program</a></li><li><a href="https://cloud.google.com/billing/docs/how-to/budgets" target="_blank" rel="noreferrer">GCP budgets and alerts</a></li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./gemini-cheatsheet.html#subscription-tiers">Cheatsheet</a> — the full four-tier comparison</li><li><a href="./gemini-cookbook.html#_14-you-got-google-cloud-credit-and-worry-about-overspending">Cookbook</a> — the budget configuration recipe</li></ul>`,42)])])}const b=e(i,[["render",n]]);export{f as __pageData,b as default};
